"""YAML renderer — standard library only (uses repr-based output)."""

from plugins import PluginError, Renderer, register


def _yaml_value(v):
    """Return a YAML-safe string representation of a scalar value."""
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        return str(v)
    # string
    s = str(v)
    # Quote if it could be misinterpreted or contains special chars
    if (
        not s
        or s in ("true", "false", "null", "yes", "no", "on", "off")
        or s[0] in ('"', "'", "{", "[", "&", "*", "!", "|", ">", "'", "%", "@", "`")
        or s[-1] in (" ", "\t")
        or "\n" in s
        or ": " in s
        or s.startswith(" -")
    ):
        # Use single quotes; escape internal single quotes by doubling
        escaped = s.replace("'", "''")
        return f"'{escaped}'"
    return s


def _yaml_scalar(v):
    """Format a single scalar value for YAML."""
    return _yaml_value(v)


@register("yaml")
class YamlRenderer(Renderer):
    def render(self, rows: list[dict]) -> str:
        if not isinstance(rows, list) or not rows:
            raise PluginError("yaml needs a non-empty list of dicts")
        if not all(isinstance(r, dict) for r in rows):
            raise PluginError("yaml needs a non-empty list of dicts")
        keys = list(rows[0])
        lines: list[str] = []
        for i, row in enumerate(rows):
            if list(row) != keys:
                raise PluginError("all rows must share the same keys")
            lines.append(f"- {keys[0]}: {_yaml_scalar(row[keys[0]])}")
            for k in keys[1:]:
                lines.append(f"  {k}: {_yaml_scalar(row[k])}")
        return "\n".join(lines) + "\n"

